  SIGNAL Complex_to_Real_Imag_out1        : vector_of_signed12(0 TO 2047);  -- sfix12_En11 [2048]
  SIGNAL delayMatch3_reg                  : vector_of_signed12(0 TO 6143);  -- sfix12 [6144]
  SIGNAL Complex_to_Real_Imag_out2        : vector_of_signed12(0 TO 2047);  -- sfix12_En11 [2048]
  SIGNAL BUF_MIN_MAX_AVG_out1             : vector_of_std_logic_vector12(0 TO 2047);  -- ufix12 [2048]
  SIGNAL BUF_MIN_MAX_AVG_out2             : std_logic_vector(15 DOWNTO 0);  -- ufix16
  SIGNAL BUF_MIN_MAX_AVG_out3             : std_logic_vector(15 DOWNTO 0);  -- ufix16
  SIGNAL BUF_MIN_MAX_AVG_out4             : std_logic;
  SIGNAL BUF_MIN_MAX_AVG_out2_unsigned    : unsigned(15 DOWNTO 0);  -- ufix16_En16
