  SIGNAL BUF_MIN_MAX_AVG_out2_1           : unsigned(15 DOWNTO 0);  -- ufix16_En16
  SIGNAL BUF_MIN_MAX_AVG_out3_signed      : signed(15 DOWNTO 0);  -- sfix16_En15
  SIGNAL delayMatch5_reg                  : vector_of_signed16(0 TO 2);  -- sfix16 [3]
