  SIGNAL Subsystem_Reference_out2         : std_logic;
  SIGNAL BUF_MIN_MAX_AVG_out1_signed      : vector_of_signed12(0 TO 2047);  -- sfix12_En11 [2048]
  SIGNAL delayMatch6_reg                  : vector_of_signed12(0 TO 6143);  -- sfix12 [6144]
  SIGNAL BUF_MIN_MAX_AVG_out1_1           : vector_of_signed12(0 TO 2047);  -- sfix12_En11 [2048]
  SIGNAL myRMS_out1                       : std_logic_vector(15 DOWNTO 0);  -- ufix16
  SIGNAL myRMS_out2                       : std_logic;
  SIGNAL delayMatch_reg                   : std_logic_vector(2 DOWNTO 0);  -- ufix1 [3]
  SIGNAL S_R_Flip_Flop_out1_1             : std_logic;
  SIGNAL delayMatch1_reg                  : std_logic_vector(2 DOWNTO 0);  -- ufix1 [3]
  SIGNAL BUF_MIN_MAX_AVG_out4_1           : std_logic;
  SIGNAL OR_out1                          : std_logic;
  SIGNAL Buffer_signed                    : signed(11 DOWNTO 0);  -- sfix12_En11

BEGIN
  -- Divide by FFT length shift

  u_Subsystem1_tc : Subsystem_ip_src_Subsystem1_tc
    PORT MAP( clk => clk,
              reset => reset,
              clk_enable => clk_enable,
              enb_1_25_0 => enb_1_25_0,
              enb_1_25_1 => enb_1_25_1,
              enb_1_51200_0 => enb_1_51200_0
              );

